var import_obsidian6 = require("obsidian");
var EditJournalHeaderModal = class extends import_obsidian6.Modal {
  constructor(app, currentHeader, onSave) {
    super(app);
    const { contentEl } = this;
    let header = currentHeader;
    new import_obsidian6.Setting(contentEl).setName("Edit Journal Header").setHeading();
    const descFragment = document.createDocumentFragment();
    descFragment.appendText("The header text which the plugin should search for journal information.");
    descFragment.createEl("br");
    descFragment.appendText("Include exact markdown syntax. Leave blank if unknown.");
    new import_obsidian6.Setting(contentEl).setName("Journal Header").setDesc(descFragment).addText((t) => {
      t.setValue(currentHeader);
      t.onChange((v) => header = v);
      setTimeout(() => {
        t.inputEl.focus();
      }, 10);
    });
    new import_obsidian6.Setting(contentEl).addButton((b) => b.setButtonText("Save").setCta().onClick(() => {
      onSave(header);
      this.close();
    })).addButton((b) => b.setButtonText("Cancel").onClick(() => this.close()));
  }
};

